<h2>Analyze word and phrase frequency</h2><p class="lead">Paste text to inspect total words, unique words, reading time and common one-, two- and three-word phrases.</p><div class="field"><label for="text">Text to analyze</label><textarea id="text" style="min-height:230px" placeholder="Paste your article, landing page copy or draft here…"></textarea></div><div class="tool-actions"><label class="helper"><input type="checkbox" id="stop" checked> Exclude common English stop words from single-word table</label><button class="btn btn-primary" id="analyze">Analyze</button></div><div class="result-box" id="result" hidden><div class="result-grid"><div class="metric"><span>Total words</span><strong id="words">0</strong></div><div class="metric"><span>Unique words</span><strong id="unique">0</strong></div><div class="metric"><span>Reading time</span><strong id="reading">0 min</strong></div></div><h3>Top words</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Term</th><th>Count</th><th>Density</th></tr></thead><tbody id="one"></tbody></table></div><h3>Top two-word phrases</h3><div class="table-wrap"><table class="data-table"><tbody id="two"></tbody></table></div><h3>Top three-word phrases</h3><div class="table-wrap"><table class="data-table"><tbody id="three"></tbody></table></div></div>
<script>(()=>{const stop=new Set('a an and are as at be but by for from has have he her his i if in into is it its me my of on or our she so that the their them there they this to was we were what when where which who will with you your'.split(' '));const $=i=>document.getElementById(i);function freq(a){const m={};a.forEach(x=>m[x]=(m[x]||0)+1);return Object.entries(m).sort((a,b)=>b[1]-a[1])}function ngrams(a,n){const z=[];for(let i=0;i<=a.length-n;i++)z.push(a.slice(i,i+n).join(' '));return freq(z)}function rows(arr,total,density=true){return arr.slice(0,12).map(([x,c])=>`<tr><td>${x.replace(/[&<>]/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[s]))}</td><td>${c}</td>${density?`<td>${(c/total*100).toFixed(2)}%</td>`:''}</tr>`).join('')}function go(){const tokens=($('text').value.toLowerCase().match(/[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu)||[]);$('words').textContent=tokens.length;$('unique').textContent=new Set(tokens).size;$('reading').textContent=Math.max(1,Math.ceil(tokens.length/220))+' min';const singles=$('stop').checked?tokens.filter(x=>!stop.has(x)):tokens;$('one').innerHTML=rows(freq(singles),tokens.length);$('two').innerHTML=rows(ngrams(tokens,2),tokens.length,false);$('three').innerHTML=rows(ngrams(tokens,3),tokens.length,false);$('result').hidden=false} $('analyze').onclick=go;$('stop').onchange=()=>{if(!$('result').hidden)go()}})();</script>
